{
  "appearance_facts": [
    {
      "location": "Title at top-left, approx (15, 45) to (1450, 85).",
      "fact": "The chart title reads 'Shrinking Population of City A from 2010 to 2015'. This is a strong textual cue that contradicts the visual data."
    },
    {
      "location": "Main plot area, approx (250, 300) to (2150, 1650).",
      "fact": "A single solid blue line is plotted across the graph. The line starts at the bottom-left and extends to the top-right, indicating a positive slope."
    },
    {
      "location": "Start of the line, approx (250, 870).",
      "fact": "The line begins at the year 2010 mark on the x-axis, aligning horizontally with the 2,000 tick mark on the y-axis."
    },
    {
      "location": "End of the line, approx (2150, 500).",
      "fact": "The line ends at the year 2015 mark on the x-axis, aligning horizontally with the 3,000 tick mark on the y-axis."
    },
    {
      "location": "Y-axis, left side, approx (200, 300) to (200, 1650).",
      "fact": "The vertical axis is labeled 'Population' and features tick marks at intervals of 500, ranging from 0 to 3,500."
    },
    {
      "location": "X-axis, bottom, approx (250, 1650) to (2150, 1650).",
      "fact": "The horizontal axis is labeled 'Year' and features tick marks for each year from 2010 to 2015."
    },
    {
      "location": "General visual impression.",
      "fact": "Despite the title claiming a 'Shrinking Population', the graphical representation clearly shows a steady, linear increase in population over the 5-year period."
    }
  ],
  "printed_facts": [
    {
      "location": "Y-axis label, approx (150, 900).",
      "fact": "Label: 'Population'"
    },
    {
      "location": "X-axis label, approx (1200, 1720).",
      "fact": "Label: 'Year'"
    },
    {
      "location": "Y-axis ticks, approx (180, 300) to (180, 1650).",
      "fact": "Values: 0, 500, 1,000, 1,500, 2,000, 2,500, 3,000, 3,500"
    },
    {
      "location": "X-axis ticks, approx (250, 1670) to (2150, 1670).",
      "fact": "Values: 2010, 2011, 2012, 2013, 2014, 2015"
    },
    {
      "location": "Data point at 2010, approx (250, 870).",
      "fact": "Population value is 2,000."
    },
    {
      "location": "Data point at 2015, approx (2150, 500).",
      "fact": "Population value is 3,000."
    },
    {
      "location": "Title, approx (15, 45).",
      "fact": "Text: 'Shrinking Population of City A from 2010 to 2015'"
    }
  ],
  "public_definitions": [
    "Route to population growth planning",
    "Route to population decline response",
    "Keep on routine population monitoring"
  ],
